Disease-free equilibrium check
With transmission switched off, hospital occupancy and hospital susceptibility must stay flat. Drift means the inputs are inconsistent and every fit inherits an artificial transient.

disease_free &lt;- function(days = 365) {

  p &lt;- make_params(c(beta_C = 0, kappa = 0, p_a = 0.1))   # no transmission

  ode(y = init_state(0), times = 0:days,
      func = measles_ode, parms = p,
      method = "lsoda", atol = 1e-3, rtol = 1e-6) |&gt;
    as.data.frame() |&gt;
    as_tibble() |&gt;
    transmute(
      day = time,
      N_H = S_H + E_H + I_H_pre + I_H_post + Q + R_H,
      s_H = S_H / (S_H + E_H + I_H_pre + I_H_post + R_H),
      s_C = S_C / (S_C + E_C + I_C_pre + I_C_post + R_C)
    )
}

df_check &lt;- disease_free()

df_check |&gt;
  summarise(N_H_drift_pct = 100 * (last(N_H) / first(N_H) - 1),
            s_H_drift_pct = 100 * (last(s_H) / first(s_H) - 1),
            s_C_drift_pct = 100 * (last(s_C) / first(s_C) - 1))

