clean_district &lt;- function(x) {
  x |&gt;
    stri_trans_general("Latin-ASCII") |&gt; 
    str_to_lower() |&gt;                      
    str_squish() |&gt;                        
    str_replace_all("đ", "d") |&gt;
    str_remove("^(quan |huyen |thanh pho |tp )")
}

clean_province &lt;- function(x) {
  x |&gt;
    stri_trans_general("Latin-ASCII") |&gt; 
    str_to_lower() |&gt;
    str_squish() |&gt;
    str_replace_all("đ", "d")
}

